/* @lc app=leetcode id=3235 lang=kotlin */
class Solution { fun canReachCorner(X: Int, Y: Int, A: Array<IntArray>): Boolean = A.size.let { n -> IntArray(n + 2) { it }.let { f -> Array<(Int) -> Int>(1) { { 0 } }.apply { this[0] = { i -> if (f[i] == i) i else this[0](f[i]).also { f[i] = it } } }.let { find -> { a: Int, b: Int -> find[0](a).let { ra -> find[0](b).let { rb -> if (ra != rb) f[ra] = rb else Unit } } }.let { union -> (0 until n).forEach { i -> A[i].let { ai -> ai[0].toLong().let { x -> ai[1].toLong().let { y -> ai[2].toLong().let { r -> maxOf(0L, minOf(X.toLong(), x)).let { cx -> maxOf(0L, minOf(Y.toLong(), y)).let { cy -> (if ((x - cx) * (x - cx) + (y - Y) * (y - Y) <= r * r || x * x + (y - cy) * (y - cy) <= r * r) union(n, i) else Unit).run { if ((x - cx) * (x - cx) + y * y <= r * r || (x - X) * (x - X) + (y - cy) * (y - cy) <= r * r) union(n + 1, i) else Unit }.run { (0 until i).forEach { j -> A[j].let { aj -> aj[0].toLong().let { xj -> aj[1].toLong().let { yj -> aj[2].toLong().let { rj -> if ((x - xj) * (x - xj) + (y - yj) * (y - yj) <= (r + rj) * (r + rj) && x * rj + xj * r <= X * (r + rj) && y * rj + yj * r <= Y * (r + rj)) union(i, j) else Unit } } } } } } } } } } } }.run { find[0](n) != find[0](n + 1) } } } } } }